macro_rules! deps {
    () => {
        SanitizerSet!();
        LinkArgsCli!();
        ABI!();
        LinkSelfContainedDefault!();
        StackProbeType!();
        LinkerFlavorCli!();
        LinkArgs!();
        StaticCow!();
        LinkerFlavor!();
        CrtObjects!();
        Target!();
        SmallDataThresholdSupport!();
    };
}

macro_rules! TargetOptions {
    () => {
        deps!();
        # [doc = " Optional aspects of a target specification."] # [doc = ""] # [doc = " This has an implementation of `Default`, see each field for what the default is. In general,"] # [doc = " these try to take \"minimal defaults\" that don't assume anything about the runtime they run in."] # [doc = ""] # [doc = " `TargetOptions` as a separate structure is mostly an implementation detail of `Target`"] # [doc = " construction, all its fields logically belong to `Target` and available from `Target`"] # [doc = " through `Deref` impls."] # [derive (PartialEq , Clone , Debug)] pub struct TargetOptions { # [doc = " Used as the `target_endian` `cfg` variable. Defaults to little endian."] pub endian : Endian , # [doc = " Width of c_int type. Defaults to \"32\"."] pub c_int_width : u16 , # [doc = " OS name to use for conditional compilation (`target_os`). Defaults to \"none\"."] # [doc = " \"none\" implies a bare metal target without `std` library."] # [doc = " A couple of targets having `std` also use \"unknown\" as an `os` value,"] # [doc = " but they are exceptions."] pub os : StaticCow < str > , # [doc = " Environment name to use for conditional compilation (`target_env`). Defaults to \"\"."] pub env : StaticCow < str > , # [doc = " ABI name to distinguish multiple ABIs on the same OS and architecture. For instance, `\"eabi\"`"] # [doc = " or `\"eabihf\"`. Defaults to \"\"."] # [doc = " This field is *not* forwarded directly to LLVM; its primary purpose is `cfg(target_abi)`."] # [doc = " However, parts of the backend do check this field for specific values to enable special behavior."] pub abi : StaticCow < str > , # [doc = " Vendor name to use for conditional compilation (`target_vendor`). Defaults to \"unknown\"."] pub vendor : StaticCow < str > , # [doc = " Linker to invoke"] pub linker : Option < StaticCow < str > > , # [doc = " Default linker flavor used if `-C linker-flavor` or `-C linker` are not passed"] # [doc = " on the command line. Defaults to `LinkerFlavor::Gnu(Cc::Yes, Lld::No)`."] pub linker_flavor : LinkerFlavor , linker_flavor_json : LinkerFlavorCli , lld_flavor_json : LldFlavor , linker_is_gnu_json : bool , # [doc = " Objects to link before and after all other object code."] pub pre_link_objects : CrtObjects , pub post_link_objects : CrtObjects , # [doc = " Same as `(pre|post)_link_objects`, but when self-contained linking mode is enabled."] pub pre_link_objects_self_contained : CrtObjects , pub post_link_objects_self_contained : CrtObjects , # [doc = " Behavior for the self-contained linking mode: inferred for some targets, or explicitly"] # [doc = " enabled (in bulk, or with individual components)."] pub link_self_contained : LinkSelfContainedDefault , # [doc = " Linker arguments that are passed *before* any user-defined libraries."] pub pre_link_args : LinkArgs , pre_link_args_json : LinkArgsCli , # [doc = " Linker arguments that are unconditionally passed after any"] # [doc = " user-defined but before post-link objects. Standard platform"] # [doc = " libraries that should be always be linked to, usually go here."] pub late_link_args : LinkArgs , late_link_args_json : LinkArgsCli , # [doc = " Linker arguments used in addition to `late_link_args` if at least one"] # [doc = " Rust dependency is dynamically linked."] pub late_link_args_dynamic : LinkArgs , late_link_args_dynamic_json : LinkArgsCli , # [doc = " Linker arguments used in addition to `late_link_args` if all Rust"] # [doc = " dependencies are statically linked."] pub late_link_args_static : LinkArgs , late_link_args_static_json : LinkArgsCli , # [doc = " Linker arguments that are unconditionally passed *after* any"] # [doc = " user-defined libraries."] pub post_link_args : LinkArgs , post_link_args_json : LinkArgsCli , # [doc = " Optional link script applied to `dylib` and `executable` crate types."] # [doc = " This is a string containing the script, not a path. Can only be applied"] # [doc = " to linkers where linker flavor matches `LinkerFlavor::Gnu(..)`."] pub link_script : Option < StaticCow < str > > , # [doc = " Environment variables to be set for the linker invocation."] pub link_env : StaticCow < [(StaticCow < str > , StaticCow < str >)] > , # [doc = " Environment variables to be removed for the linker invocation."] pub link_env_remove : StaticCow < [StaticCow < str >] > , # [doc = " Extra arguments to pass to the external assembler (when used)"] pub asm_args : StaticCow < [StaticCow < str >] > , # [doc = " Default CPU to pass to LLVM. Corresponds to `llc -mcpu=$cpu`. Defaults"] # [doc = " to \"generic\"."] pub cpu : StaticCow < str > , # [doc = " Whether a cpu needs to be explicitly set."] # [doc = " Set to true if there is no default cpu. Defaults to false."] pub need_explicit_cpu : bool , # [doc = " Default target features to pass to LLVM. These features overwrite"] # [doc = " `-Ctarget-cpu` but can be overwritten with `-Ctarget-features`."] # [doc = " Corresponds to `llc -mattr=$features`."] # [doc = " Note that these are LLVM feature names, not Rust feature names!"] # [doc = ""] # [doc = " Generally it is a bad idea to use negative target features because they often interact very"] # [doc = " poorly with how `-Ctarget-cpu` works. Instead, try to use a lower \"base CPU\" and enable the"] # [doc = " features you want to use."] pub features : StaticCow < str > , # [doc = " Direct or use GOT indirect to reference external data symbols"] pub direct_access_external_data : Option < bool > , # [doc = " Whether dynamic linking is available on this target. Defaults to false."] pub dynamic_linking : bool , # [doc = " Whether dynamic linking can export TLS globals. Defaults to true."] pub dll_tls_export : bool , # [doc = " If dynamic linking is available, whether only cdylibs are supported."] pub only_cdylib : bool , # [doc = " Whether executables are available on this target. Defaults to true."] pub executables : bool , # [doc = " Relocation model to use in object file. Corresponds to `llc"] # [doc = " -relocation-model=$relocation_model`. Defaults to `Pic`."] pub relocation_model : RelocModel , # [doc = " Code model to use. Corresponds to `llc -code-model=$code_model`."] # [doc = " Defaults to `None` which means \"inherited from the base LLVM target\"."] pub code_model : Option < CodeModel > , # [doc = " TLS model to use. Options are \"global-dynamic\" (default), \"local-dynamic\", \"initial-exec\""] # [doc = " and \"local-exec\". This is similar to the -ftls-model option in GCC/Clang."] pub tls_model : TlsModel , # [doc = " Do not emit code that uses the \"red zone\", if the ABI has one. Defaults to false."] pub disable_redzone : bool , # [doc = " Frame pointer mode for this target. Defaults to `MayOmit`."] pub frame_pointer : FramePointer , # [doc = " Emit each function in its own section. Defaults to true."] pub function_sections : bool , # [doc = " String to prepend to the name of every dynamic library. Defaults to \"lib\"."] pub dll_prefix : StaticCow < str > , # [doc = " String to append to the name of every dynamic library. Defaults to \".so\"."] pub dll_suffix : StaticCow < str > , # [doc = " String to append to the name of every executable."] pub exe_suffix : StaticCow < str > , # [doc = " String to prepend to the name of every static library. Defaults to \"lib\"."] pub staticlib_prefix : StaticCow < str > , # [doc = " String to append to the name of every static library. Defaults to \".a\"."] pub staticlib_suffix : StaticCow < str > , # [doc = " Values of the `target_family` cfg set for this target."] # [doc = ""] # [doc = " Common options are: \"unix\", \"windows\". Defaults to no families."] # [doc = ""] # [doc = " See <https://doc.rust-lang.org/reference/conditional-compilation.html#target_family>."] pub families : StaticCow < [StaticCow < str >] > , # [doc = " Whether the target toolchain's ABI supports returning small structs as an integer."] pub abi_return_struct_as_int : bool , # [doc = " Whether the target toolchain is like AIX's. Linker options on AIX are special and it uses"] # [doc = " XCOFF as binary format. Defaults to false."] pub is_like_aix : bool , # [doc = " Whether the target toolchain is like macOS's. Only useful for compiling against iOS/macOS,"] # [doc = " in particular running dsymutil and some other stuff like `-dead_strip`. Defaults to false."] # [doc = " Also indicates whether to use Apple-specific ABI changes, such as extending function"] # [doc = " parameters to 32-bits."] pub is_like_darwin : bool , # [doc = " Whether the target toolchain is like Solaris's."] # [doc = " Only useful for compiling against Illumos/Solaris,"] # [doc = " as they have a different set of linker flags. Defaults to false."] pub is_like_solaris : bool , # [doc = " Whether the target is like Windows."] # [doc = " This is a combination of several more specific properties represented as a single flag:"] # [doc = "   - The target uses a Windows ABI,"] # [doc = "   - uses PE/COFF as a format for object code,"] # [doc = "   - uses Windows-style dllexport/dllimport for shared libraries,"] # [doc = "   - uses import libraries and .def files for symbol exports,"] # [doc = "   - executables support setting a subsystem."] pub is_like_windows : bool , # [doc = " Whether the target is like MSVC."] # [doc = " This is a combination of several more specific properties represented as a single flag:"] # [doc = "   - The target has all the properties from `is_like_windows`"] # [doc = "     (for in-tree targets \"is_like_msvc ⇒ is_like_windows\" is ensured by a unit test),"] # [doc = "   - has some MSVC-specific Windows ABI properties,"] # [doc = "   - uses a link.exe-like linker,"] # [doc = "   - uses CodeView/PDB for debuginfo and natvis for its visualization,"] # [doc = "   - uses SEH-based unwinding,"] # [doc = "   - supports control flow guard mechanism."] pub is_like_msvc : bool , # [doc = " Whether a target toolchain is like WASM."] pub is_like_wasm : bool , # [doc = " Whether a target toolchain is like Android, implying a Linux kernel and a Bionic libc"] pub is_like_android : bool , # [doc = " Whether a target toolchain is like VEXos, the operating system used by the VEX Robotics V5 Brain."] pub is_like_vexos : bool , # [doc = " Target's binary file format. Defaults to BinaryFormat::Elf"] pub binary_format : BinaryFormat , # [doc = " Default supported version of DWARF on this platform."] # [doc = " Useful because some platforms (osx, bsd) only want up to DWARF2."] pub default_dwarf_version : u32 , # [doc = " The MinGW toolchain has a known issue that prevents it from correctly"] # [doc = " handling COFF object files with more than 2<sup>15</sup> sections. Since each weak"] # [doc = " symbol needs its own COMDAT section, weak linkage implies a large"] # [doc = " number sections that easily exceeds the given limit for larger"] # [doc = " codebases. Consequently we want a way to disallow weak linkage on some"] # [doc = " platforms."] pub allows_weak_linkage : bool , # [doc = " Whether the linker support rpaths or not. Defaults to false."] pub has_rpath : bool , # [doc = " Whether to disable linking to the default libraries, typically corresponds"] # [doc = " to `-nodefaultlibs`. Defaults to true."] pub no_default_libraries : bool , # [doc = " Dynamically linked executables can be compiled as position independent"] # [doc = " if the default relocation model of position independent code is not"] # [doc = " changed. This is a requirement to take advantage of ASLR, as otherwise"] # [doc = " the functions in the executable are not randomized and can be used"] # [doc = " during an exploit of a vulnerability in any code."] pub position_independent_executables : bool , # [doc = " Executables that are both statically linked and position-independent are supported."] pub static_position_independent_executables : bool , # [doc = " Determines if the target always requires using the PLT for indirect"] # [doc = " library calls or not. This controls the default value of the `-Z plt` flag."] pub plt_by_default : bool , # [doc = " Either partial, full, or off. Full RELRO makes the dynamic linker"] # [doc = " resolve all symbols at startup and marks the GOT read-only before"] # [doc = " starting the program, preventing overwriting the GOT."] pub relro_level : RelroLevel , # [doc = " Format that archives should be emitted in. This affects whether we use"] # [doc = " LLVM to assemble an archive or fall back to the system linker, and"] # [doc = " currently only \"gnu\" is used to fall into LLVM. Unknown strings cause"] # [doc = " the system linker to be used."] pub archive_format : StaticCow < str > , # [doc = " Is asm!() allowed? Defaults to true."] pub allow_asm : bool , # [doc = " Whether the runtime startup code requires the `main` function be passed"] # [doc = " `argc` and `argv` values."] pub main_needs_argc_argv : bool , # [doc = " Flag indicating whether #[thread_local] is available for this target."] pub has_thread_local : bool , # [doc = " This is mainly for easy compatibility with emscripten."] # [doc = " If we give emcc .o files that are actually .bc files it"] # [doc = " will 'just work'."] pub obj_is_bitcode : bool , # [doc = " Don't use this field; instead use the `.min_atomic_width()` method."] pub min_atomic_width : Option < u64 > , # [doc = " Don't use this field; instead use the `.max_atomic_width()` method."] pub max_atomic_width : Option < u64 > , # [doc = " Whether the target supports atomic CAS operations natively"] pub atomic_cas : bool , # [doc = " Panic strategy: \"unwind\" or \"abort\""] pub panic_strategy : PanicStrategy , # [doc = " Whether or not linking dylibs to a static CRT is allowed."] pub crt_static_allows_dylibs : bool , # [doc = " Whether or not the CRT is statically linked by default."] pub crt_static_default : bool , # [doc = " Whether or not crt-static is respected by the compiler (or is a no-op)."] pub crt_static_respected : bool , # [doc = " The implementation of stack probes to use."] pub stack_probes : StackProbeType , # [doc = " The minimum alignment for global symbols."] pub min_global_align : Option < Align > , # [doc = " Default number of codegen units to use in debug mode"] pub default_codegen_units : Option < u64 > , # [doc = " Default codegen backend used for this target. Defaults to `None`."] # [doc = ""] # [doc = " If `None`, then `CFG_DEFAULT_CODEGEN_BACKEND` environmental variable captured when"] # [doc = " compiling `rustc` will be used instead (or llvm if it is not set)."] # [doc = ""] # [doc = " N.B. when *using* the compiler, backend can always be overridden with `-Zcodegen-backend`."] # [doc = ""] # [doc = " This was added by WaffleLapkin in #116793. The motivation is a rustc fork that requires a"] # [doc = " custom codegen backend for a particular target."] pub default_codegen_backend : Option < StaticCow < str > > , # [doc = " Whether to generate trap instructions in places where optimization would"] # [doc = " otherwise produce control flow that falls through into unrelated memory."] pub trap_unreachable : bool , # [doc = " This target requires everything to be compiled with LTO to emit a final"] # [doc = " executable, aka there is no native linker for this target."] pub requires_lto : bool , # [doc = " This target has no support for threads."] pub singlethread : bool , # [doc = " Whether library functions call lowering/optimization is disabled in LLVM"] # [doc = " for this target unconditionally."] pub no_builtins : bool , # [doc = " The default visibility for symbols in this target."] # [doc = ""] # [doc = " This value typically shouldn't be accessed directly, but through the"] # [doc = " `rustc_session::Session::default_visibility` method, which allows `rustc` users to override"] # [doc = " this setting using cmdline flags."] pub default_visibility : Option < SymbolVisibility > , # [doc = " Whether a .debug_gdb_scripts section will be added to the output object file"] pub emit_debug_gdb_scripts : bool , # [doc = " Whether or not to unconditionally `uwtable` attributes on functions,"] # [doc = " typically because the platform needs to unwind for things like stack"] # [doc = " unwinders."] pub requires_uwtable : bool , # [doc = " Whether or not to emit `uwtable` attributes on functions if `-C force-unwind-tables`"] # [doc = " is not specified and `uwtable` is not required on this target."] pub default_uwtable : bool , # [doc = " Whether or not SIMD types are passed by reference in the Rust ABI,"] # [doc = " typically required if a target can be compiled with a mixed set of"] # [doc = " target features. This is `true` by default, and `false` for targets like"] # [doc = " wasm32 where the whole program either has simd or not."] pub simd_types_indirect : bool , # [doc = " Pass a list of symbol which should be exported in the dylib to the linker."] pub limit_rdylib_exports : bool , # [doc = " If set, have the linker export exactly these symbols, instead of using"] # [doc = " the usual logic to figure this out from the crate itself."] pub override_export_symbols : Option < StaticCow < [StaticCow < str >] > > , # [doc = " Determines how or whether the MergeFunctions LLVM pass should run for"] # [doc = " this target. Either \"disabled\", \"trampolines\", or \"aliases\"."] # [doc = " The MergeFunctions pass is generally useful, but some targets may need"] # [doc = " to opt out. The default is \"aliases\"."] # [doc = ""] # [doc = " Workaround for: <https://github.com/rust-lang/rust/issues/57356>"] pub merge_functions : MergeFunctions , # [doc = " Use platform dependent mcount function"] pub mcount : StaticCow < str > , # [doc = " Use LLVM intrinsic for mcount function name"] pub llvm_mcount_intrinsic : Option < StaticCow < str > > , # [doc = " LLVM ABI name, corresponds to the '-mabi' parameter available in multilib C compilers"] # [doc = " and the `-target-abi` flag in llc. In the LLVM API this is `MCOptions.ABIName`."] pub llvm_abiname : StaticCow < str > , # [doc = " Control the float ABI to use, for architectures that support it. The only architecture we"] # [doc = " currently use this for is ARM. Corresponds to the `-float-abi` flag in llc. In the LLVM API"] # [doc = " this is `FloatABIType`. (clang's `-mfloat-abi` is similar but more complicated since it"] # [doc = " can also affect the `soft-float` target feature.)"] # [doc = ""] # [doc = " If not provided, LLVM will infer the float ABI from the target triple (`llvm_target`)."] pub llvm_floatabi : Option < FloatAbi > , # [doc = " Picks a specific ABI for this target. This is *not* just for \"Rust\" ABI functions,"] # [doc = " it can also affect \"C\" ABI functions; the point is that this flag is interpreted by"] # [doc = " rustc and not forwarded to LLVM."] # [doc = " So far, this is only used on x86."] pub rustc_abi : Option < RustcAbi > , # [doc = " Whether or not RelaxElfRelocation flag will be passed to the linker"] pub relax_elf_relocations : bool , # [doc = " Additional arguments to pass to LLVM, similar to the `-C llvm-args` codegen option."] pub llvm_args : StaticCow < [StaticCow < str >] > , # [doc = " Whether to use legacy .ctors initialization hooks rather than .init_array. Defaults"] # [doc = " to false (uses .init_array)."] pub use_ctors_section : bool , # [doc = " Whether the linker is instructed to add a `GNU_EH_FRAME` ELF header"] # [doc = " used to locate unwinding information is passed"] # [doc = " (only has effect if the linker is `ld`-like)."] pub eh_frame_header : bool , # [doc = " Is true if the target is an ARM architecture using thumb v1 which allows for"] # [doc = " thumb and arm interworking."] pub has_thumb_interworking : bool , # [doc = " Which kind of debuginfo is used by this target?"] pub debuginfo_kind : DebuginfoKind , # [doc = " How to handle split debug information, if at all. Specifying `None` has"] # [doc = " target-specific meaning."] pub split_debuginfo : SplitDebuginfo , # [doc = " Which kinds of split debuginfo are supported by the target?"] pub supported_split_debuginfo : StaticCow < [SplitDebuginfo] > , # [doc = " The sanitizers supported by this target"] # [doc = ""] # [doc = " Note that the support here is at a codegen level. If the machine code with sanitizer"] # [doc = " enabled can generated on this target, but the necessary supporting libraries are not"] # [doc = " distributed with the target, the sanitizer should still appear in this list for the target."] pub supported_sanitizers : SanitizerSet , # [doc = " Minimum number of bits in #[repr(C)] enum. Defaults to the size of c_int"] pub c_enum_min_bits : Option < u64 > , # [doc = " Whether or not the DWARF `.debug_aranges` section should be generated."] pub generate_arange_section : bool , # [doc = " Whether the target supports stack canary checks. `true` by default,"] # [doc = " since this is most common among tier 1 and tier 2 targets."] pub supports_stack_protector : bool , # [doc = " The name of entry function."] # [doc = " Default value is \"main\""] pub entry_name : StaticCow < str > , # [doc = " The ABI of the entry function."] # [doc = " Default value is `CanonAbi::C`"] pub entry_abi : CanonAbi , # [doc = " Whether the target supports XRay instrumentation."] pub supports_xray : bool , # [doc = " The default address space for this target. When using LLVM as a backend, most targets simply"] # [doc = " use LLVM's default address space (0). Some other targets, such as CHERI targets, use a"] # [doc = " custom default address space (in this specific case, `200`)."] pub default_address_space : rustc_abi :: AddressSpace , # [doc = " Whether the targets supports -Z small-data-threshold"] small_data_threshold_support : SmallDataThresholdSupport , }
    };
}

TargetOptions!();